<script setup lang="ts">
import { computed, inject, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from "vue";
import { PhArchive as Archive, PhArrowClockwise as ArrowClockwise, PhArrowLeft as ArrowLeft, PhCaretLeft as CaretLeft, PhCaretRight as CaretRight, PhEnvelopeOpen as EnvelopeOpen, PhFileArrowDown as FileArrowDown, PhMagnifyingGlass as MagnifyingGlass, PhPaperPlaneTilt as PaperPlaneTilt, PhPlus as Plus, PhStar as Star, PhTrash as Trash, PhX as X } from "@phosphor-icons/vue";
import { APIProblem, type APIClient } from "../api";
import { sessionStore } from "../store";

interface Account { id:string;display_label:string;address:string;authorization_epoch:number }
interface Folder { name:string;parent?:string;delimiter?:string;subscribed:boolean;has_children:boolean;role?:string;messages:number;unseen:number;uid_validity:number;quota?:{used_bytes:number;limit_bytes:number} }
interface MessageIdentity { folder:string;uid_validity:number;uid:number }
interface Address { name?:string;address:string }
interface MessageSummary { identity:MessageIdentity;mod_seq:number;thread_id:string;flags:string[];sender:Address;subject:string;date:string;size:number;has_attachment:boolean;searchOnly?:boolean }
interface RemoteImageReference { id:string;url:string;digest:string;blocked:boolean }
interface AttachmentReference { part_id:string;filename:string;content_type:string;size:number;size_unknown?:boolean }
interface RenderedMessage { identity:MessageIdentity;plain_text?:string;sanitized_html?:string;csp:string;referrer_policy:string;remote_images:RemoteImageReference[];attachments?:AttachmentReference[] }
interface PageSnapshot { items:MessageSummary[];nextCursor:string;partial:boolean }
interface BlobProjection { id:string;filename:string;content_type:string;size:number;digest:string;expires_at:string }
interface SendResult { state:"queued"|"scheduled"|"uncertain";submission_id?:string;may_have_submitted?:boolean }
type ControllerKey="bootstrap"|"folders"|"messages"|"read"|"images"|"attachments"|"compose"|"send";

const api=inject<APIClient>("api")!;
const accounts=ref<Account[]>([]);const accountNextCursor=ref("");const mailboxID=ref("");const folders=ref<Folder[]>([]);const folderNextCursor=ref("");const activeFolder=ref("");
const messagePages=ref<PageSnapshot[]>([]);const pageIndex=ref(-1);const query=ref("");const committedQuery=ref("");const selected=ref<{summary:MessageSummary;rendered:RenderedMessage}|null>(null);
const booting=ref(true);const listLoading=ref(false);const reading=ref(false);const remoteLoading=ref(false);const error=ref("");const status=ref("");const focusedMessage=ref(0);
const composeOpen=ref(false);const composeDialog=ref<HTMLElement|null>(null);const sending=ref(false);const uploading=ref(false);const draftRevision=ref(0);const sendIdempotencyKey=ref("");const submissionState=ref<"idle"|"uncertain">("idle");const uploaded=ref<BlobProjection[]>([]);
const compose=reactive({id:"",mode:"new",to:"",cc:"",bcc:"",subject:"",text:"",sendAt:""});const actionTarget=ref("");
const controllers:Record<ControllerKey,AbortController|null>={bootstrap:null,folders:null,messages:null,read:null,images:null,attachments:null,compose:null,send:null};
const remoteImageURLs=reactive<Record<string,string>>({});

const selectedAccount=computed(()=>accounts.value.find((account)=>account.id===mailboxID.value)||null);
const authorizationEpoch=computed(()=>selectedAccount.value?.authorization_epoch||0);
const currentPage=computed(()=>messagePages.value[pageIndex.value]||null);
const messages=computed(()=>currentPage.value?.items||[]);
const nextCursor=computed(()=>currentPage.value?.nextCursor||"");
const canCompose=computed(()=>api.available("webmail.message.send")&&Boolean(selectedAccount.value));
const archiveFolder=computed(()=>folders.value.find((folder)=>folder.role==="archive")?.name||"");
const junkFolder=computed(()=>folders.value.find((folder)=>folder.role==="junk")?.name||"");
const inboxFolder=computed(()=>folders.value.find((folder)=>folder.role==="inbox")?.name||folders.value[0]?.name||"");
const selectedFolderRole=computed(()=>folders.value.find((folder)=>folder.name===activeFolder.value)?.role||"");
const iframeDocument=computed(()=>{
  const rendered=selected.value?.rendered;if(!rendered)return "";const parser=new DOMParser();const body=rendered.sanitized_html||`<pre>${escapeHTML(rendered.plain_text||"")}</pre>`;const documentValue=parser.parseFromString(`<body>${body}</body>`,"text/html");
  for(const element of Array.from(documentValue.querySelectorAll<HTMLElement>("[data-remote-image-id]"))){const id=element.dataset.remoteImageId||"";const source=remoteImageURLs[id];if(source&&element instanceof HTMLImageElement){element.src=source;element.removeAttribute("data-remote-image-id")}}
  let csp=rendered.csp||"default-src 'none'; base-uri 'none'; form-action 'none'; script-src 'none'; object-src 'none'";if(Object.keys(remoteImageURLs).length)csp=csp.replace("img-src 'self'","img-src 'self' blob:");
  return `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="${escapeAttribute(csp)}"><meta name="referrer" content="no-referrer"></head><body>${documentValue.body.innerHTML}</body></html>`;
});

onMounted(()=>void bootstrap());
onBeforeUnmount(()=>{for(const key of Object.keys(controllers) as ControllerKey[])controllers[key]?.abort();clearRemoteImages()});
watch(activeFolder,(next,previous)=>{if(next&&next!==previous){actionTarget.value=folders.value.find((folder)=>folder.name!==next)?.name||"";void resetMessagePages()}});

function replaceController(key:ControllerKey):AbortController{controllers[key]?.abort();const controller=new AbortController();controllers[key]=controller;return controller}
function aborted(cause:unknown):boolean{return cause instanceof DOMException&&cause.name==="AbortError"}
function message(cause:unknown,fallback:string):string{return cause instanceof Error?cause.message:fallback}
function contextPayload():{authorization_epoch:number}{if(!mailboxID.value||!authorizationEpoch.value)throw new Error("Select an authorized mailbox first.");return {authorization_epoch:authorizationEpoch.value}}

async function bootstrap():Promise<void>{const controller=replaceController("bootstrap");booting.value=true;error.value="";status.value="";try{await loadAccounts("",false,controller.signal);const firstAccount=accounts.value[0];if(!firstAccount)throw new Error("No authorized mail account is available for this tenant.");const saved=localStorage.getItem("panel.webmail.mailbox");mailboxID.value=accounts.value.some((account)=>account.id===saved)?String(saved):firstAccount.id;localStorage.setItem("panel.webmail.mailbox",mailboxID.value);const previousFolder=activeFolder.value;await loadFolders("",false);if(activeFolder.value&&activeFolder.value===previousFolder)await resetMessagePages()}catch(cause){if(!aborted(cause))error.value=message(cause,"Webmail could not be opened.")}finally{if(controllers.bootstrap===controller)booting.value=false}}
async function loadAccounts(cursor:string,append:boolean,signal?:AbortSignal):Promise<void>{const operation=api.available("webmail.account.list")?"webmail.account.list":"webmail.mailbox.list";if(!api.available(operation))throw new Error("Secure webmail account discovery is not enabled on this node.");const response=await api.invoke<{items:Account[];next_cursor?:string}>(operation,{tenantId:sessionStore.state.tenantId,payload:{limit:100,cursor:cursor||undefined},signal});const items=Array.isArray(response.result.items)?response.result.items:[];accounts.value=append?[...accounts.value,...items]:items;accountNextCursor.value=response.result.next_cursor||""}
async function moreAccounts():Promise<void>{if(!accountNextCursor.value)return;const controller=replaceController("bootstrap");try{await loadAccounts(accountNextCursor.value,true,controller.signal)}catch(cause){if(!aborted(cause))error.value=message(cause,"More accounts could not be loaded.")}}
async function switchAccount(event:Event):Promise<void>{const target=(event.target as HTMLSelectElement).value;const previous=mailboxID.value;if(!target||target===previous)return;error.value="";status.value="Switching account…";for(const key of ["folders","messages","read","images","attachments"] as ControllerKey[])controllers[key]?.abort();try{if(previous&&api.available("webmail.account.switch"))await api.invoke("webmail.account.switch",{tenantId:sessionStore.state.tenantId,payload:{previous_mailbox_id:previous,target_mailbox_id:target}});mailboxID.value=target;localStorage.setItem("panel.webmail.mailbox",target);activeFolder.value="";folders.value=[];messagePages.value=[];selected.value=null;clearRemoteImages();await loadFolders("",false);status.value=`Opened ${selectedAccount.value?.address||target}.`}catch(cause){(event.target as HTMLSelectElement).value=previous;error.value=message(cause,"The account context could not be switched.");status.value=""}}

async function loadFolders(cursor:string,append:boolean):Promise<void>{if(!api.available("webmail.folder.list"))throw new Error("Secure folder access is not enabled on this node.");const controller=replaceController("folders");try{const response=await api.invoke<{items:Folder[];next_cursor?:string;partial?:boolean}>("webmail.folder.list",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),limit:100,cursor:cursor||undefined},signal:controller.signal});if(controllers.folders!==controller)return;const items=Array.isArray(response.result.items)?response.result.items:[];folders.value=append?[...folders.value,...items]:items;folderNextCursor.value=response.result.next_cursor||"";if(!folders.value.some((folder)=>folder.name===activeFolder.value))activeFolder.value=folders.value.find((folder)=>folder.role==="inbox")?.name||folders.value[0]?.name||"";if(response.result.partial)status.value="Folder counts are partial; refresh to reconcile them."}catch(cause){if(!aborted(cause))throw cause}}
async function moreFolders():Promise<void>{if(!folderNextCursor.value)return;try{await loadFolders(folderNextCursor.value,true)}catch(cause){error.value=message(cause,"More folders could not be loaded.")}}

async function resetMessagePages():Promise<void>{controllers.messages?.abort();controllers.read?.abort();controllers.images?.abort();clearRemoteImages();selected.value=null;messagePages.value=[];pageIndex.value=-1;if(activeFolder.value)await loadMessagePage("")}
async function loadMessagePage(cursor:string):Promise<void>{const controller=replaceController("messages");listLoading.value=true;error.value="";try{const shared={...contextPayload(),folder:activeFolder.value,limit:50,cursor:cursor||undefined,sort:"newest"};let page:{items:unknown[];next_cursor?:string;partial?:boolean};if(committedQuery.value){const response=await api.invoke<{items:MessageIdentity[];next_cursor?:string;partial?:boolean}>("webmail.message.search",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...shared,criteria:{text:committedQuery.value}},signal:controller.signal});page=response.result}else{const response=await api.invoke<{items:MessageSummary[];next_cursor?:string;partial?:boolean}>("webmail.message.list",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:shared,signal:controller.signal});page=response.result}if(controllers.messages!==controller)return;const items=committedQuery.value?(Array.isArray(page.items)?page.items:[]).map((item)=>searchSummary(item as MessageIdentity)):(Array.isArray(page.items)?page.items:[]) as MessageSummary[];const snapshot={items,nextCursor:page.next_cursor||"",partial:Boolean(page.partial)};messagePages.value=messagePages.value.slice(0,pageIndex.value+1);messagePages.value.push(snapshot);if(messagePages.value.length>20)messagePages.value.shift();pageIndex.value=messagePages.value.length-1;focusedMessage.value=0;if(snapshot.partial)status.value="This bounded page is partial; narrow the search or refresh."}catch(cause){if(!aborted(cause))error.value=message(cause,"Messages could not be loaded.")}finally{if(controllers.messages===controller)listLoading.value=false}}
function searchSummary(identity:MessageIdentity):MessageSummary{return {identity,mod_seq:0,thread_id:"",flags:[],sender:{address:"Search result"},subject:`Message ${identity.uid}`,date:"",size:0,has_attachment:false,searchOnly:true}}
function submitSearch():void{committedQuery.value=query.value.trim();void resetMessagePages()}
function nextPage():void{if(listLoading.value)return;if(pageIndex.value<messagePages.value.length-1){pageIndex.value++;selected.value=null;clearRemoteImages();focusedMessage.value=0;return}if(nextCursor.value)void loadMessagePage(nextCursor.value)}
function previousPage():void{if(pageIndex.value>0){pageIndex.value--;selected.value=null;clearRemoteImages();focusedMessage.value=0}}

async function readMessage(summary:MessageSummary):Promise<void>{const controller=replaceController("read");controllers.images?.abort();clearRemoteImages();reading.value=true;error.value="";try{const response=await api.invoke<RenderedMessage>("webmail.message.read",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),identity:summary.identity,remote_image_policy:"blocked"},signal:controller.signal});if(controllers.read!==controller)return;selected.value={summary,rendered:response.result};if(!summary.flags.includes("seen")&&api.available("webmail.message.action")){await api.invoke("webmail.message.action",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),action:"read",messages:[summary.identity]}});summary.flags.push("seen")}}catch(cause){if(!aborted(cause))error.value=message(cause,"Message content could not be loaded.")}finally{if(controllers.read===controller)reading.value=false}}
async function loadRemoteImages():Promise<void>{const view=selected.value;if(!view||!view.rendered.remote_images.length)return;const controller=replaceController("images");remoteLoading.value=true;error.value="";try{for(const reference of view.rendered.remote_images){if(controller.signal.aborted)break;if(remoteImageURLs[reference.id])continue;const response=await api.invoke<{content_type:string;content_base64:string;size:number}>("webmail.remote_image.fetch",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),identity:view.rendered.identity,reference_id:reference.id,url:reference.url,expected_digest:reference.digest,maximum_bytes:5*1024*1024},signal:controller.signal});const result=response.result;if(!result.content_type.startsWith("image/")||result.size>5*1024*1024)throw new Error("The image proxy returned an invalid image.");const bytes=decodeBase64(result.content_base64);if(bytes.byteLength!==result.size)throw new Error("The image proxy returned an incomplete image.");remoteImageURLs[reference.id]=URL.createObjectURL(new Blob([bytes],{type:result.content_type}))}status.value="Remote images loaded through the privacy proxy."}catch(cause){if(!aborted(cause))error.value=message(cause,"Remote images could not be loaded safely.")}finally{if(controllers.images===controller)remoteLoading.value=false}}
function clearRemoteImages():void{for(const value of Object.values(remoteImageURLs))URL.revokeObjectURL(value);for(const key of Object.keys(remoteImageURLs))delete remoteImageURLs[key]}

async function messageAction(action:string,targetFolder="",closeAfter=true):Promise<void>{const view=selected.value;if(!view)return;error.value="";try{const response=await api.invoke<{partial?:boolean}>("webmail.message.action",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),action,messages:[view.summary.identity],target_folder:targetFolder||undefined}});status.value=response.result.partial?`Message action ${action.replace("_"," ")} was only partially completed.`:`Message action ${action.replace("_"," ")} completed.`;if(closeAfter){selected.value=null;clearRemoteImages();await resetMessagePages()}else{if(action==="flag"&&!view.summary.flags.includes("flagged"))view.summary.flags.push("flagged");if(action==="unflag")view.summary.flags=view.summary.flags.filter((flag)=>flag!=="flagged");if(action==="read"&&!view.summary.flags.includes("seen"))view.summary.flags.push("seen");if(action==="unread")view.summary.flags=view.summary.flags.filter((flag)=>flag!=="seen")}}catch(cause){error.value=message(cause,"The message action failed.")}}
function archiveSelected():void{if(!archiveFolder.value){error.value="No unique archive folder is available.";return}void messageAction("archive",archiveFolder.value)}
function spamSelected():void{if(!junkFolder.value){error.value="No unique junk folder is available.";return}void messageAction("spam",junkFolder.value)}
function notSpamSelected():void{if(!inboxFolder.value){error.value="No inbox is available.";return}void messageAction("not_spam",inboxFolder.value)}
function moveSelected(copy:boolean):void{if(!actionTarget.value){error.value="Choose a destination folder.";return}void messageAction(copy?"copy":"move",actionTarget.value,!copy)}

async function downloadAttachment(attachment:AttachmentReference):Promise<void>{if(attachment.size>25*1024*1024){error.value="This attachment exceeds the 25 MiB transfer limit.";return}const controller=replaceController("attachments");error.value="";try{const response=await api.invoke<{download_url:string}>("webmail.attachment.issue",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),identity:selected.value?.rendered.identity,part_id:attachment.part_id,filename:attachment.filename,content_type:attachment.content_type,maximum_bytes:attachment.size_unknown?25*1024*1024:Math.max(attachment.size,1)},signal:controller.signal});if(!response.result.download_url.startsWith("/api/v1/webmail/attachments/"))throw new Error("The server returned an invalid download lease.");window.location.assign(response.result.download_url)}catch(cause){if(!aborted(cause))error.value=message(cause,"The attachment could not be downloaded.")}}

function openCompose(mode="new"):void{const view=selected.value;composeOpen.value=true;submissionState.value="idle";sendIdempotencyKey.value=`send_${crypto.randomUUID()}`;draftRevision.value=0;uploaded.value=[];Object.assign(compose,{id:`message_${crypto.randomUUID()}`,mode,to:mode==="new"?"":view?.summary.sender.address||"",cc:"",bcc:"",subject:replySubject(view?.summary.subject||"",mode),text:mode==="forward"?`\n\n---------- Forwarded message ----------\n${view?.rendered.plain_text||""}`:"",sendAt:""});void nextTick(()=>composeDialog.value?.querySelector<HTMLInputElement>("input")?.focus())}
function closeCompose():void{if(sending.value)return;controllers.compose?.abort();composeOpen.value=false}
async function uploadAttachments(event:Event):Promise<void>{const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value="";if(!files.length)return;const controller=replaceController("compose");uploading.value=true;error.value="";try{for(const file of files){if(file.size===0||file.size>8*1024*1024)throw new Error(`${file.name} must be between 1 byte and 8 MiB.`);if(!safeFilename(file.name))throw new Error(`${file.name} is not a safe attachment name.`);const content=encodeBase64(new Uint8Array(await file.arrayBuffer()));const response=await api.invoke<BlobProjection>("webmail.attachment.upload",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),filename:file.name,content_type:file.type||"application/octet-stream",maximum_bytes:file.size,expires_at:new Date(Date.now()+60*60*1000).toISOString(),content_base64:content},signal:controller.signal});uploaded.value.push(response.result)}}catch(cause){if(!aborted(cause))error.value=message(cause,"An attachment could not be uploaded.")}finally{if(controllers.compose===controller)uploading.value=false}}
async function removeUpload(blob:BlobProjection):Promise<void>{try{await api.invoke("webmail.attachment.delete",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),upload_id:blob.id}});uploaded.value=uploaded.value.filter((item)=>item.id!==blob.id)}catch(cause){error.value=message(cause,"The upload could not be removed.")}}
function composePayload():Record<string,unknown>{const sendAt=compose.sendAt?new Date(compose.sendAt).toISOString():undefined;return {id:compose.id,mode:compose.mode,from:{address:selectedAccount.value?.address||""},to:addresses(compose.to),cc:addresses(compose.cc),bcc:addresses(compose.bcc),subject:compose.subject,plain_text:compose.text,attachment_ids:uploaded.value.map((item)=>item.id),send_at:sendAt}}
async function saveDraft():Promise<void>{error.value="";try{const response=await api.invoke<{revision:number}>("webmail.draft.save",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,expectedGeneration:draftRevision.value||undefined,payload:{...contextPayload(),message:composePayload()}});draftRevision.value=response.result.revision;status.value="Draft saved."}catch(cause){error.value=message(cause,"The draft could not be saved.")}}
async function deleteDraft():Promise<void>{if(!draftRevision.value)return;try{await api.invoke("webmail.draft.delete",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,expectedGeneration:draftRevision.value,payload:{...contextPayload(),draft_id:compose.id}});draftRevision.value=0;status.value="Draft deleted."}catch(cause){error.value=message(cause,"The draft could not be deleted.")}}
async function sendMessage():Promise<void>{if(!canCompose.value||submissionState.value==="uncertain")return;const controller=replaceController("send");sending.value=true;error.value="";try{const response=await api.invoke<SendResult>("webmail.message.send",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{...contextPayload(),message:composePayload()},idempotencyKey:sendIdempotencyKey.value,signal:controller.signal});if(response.result.state==="uncertain"||response.result.may_have_submitted){submissionState.value="uncertain";error.value="Submission outcome is uncertain. Do not send this message again; inspect the delivery queue first.";return}composeOpen.value=false;status.value=response.result.state==="scheduled"?"Message scheduled.":"Message queued.";sessionStore.notify({tone:"healthy",title:response.result.state==="scheduled"?"Message scheduled":"Message queued",body:response.result.submission_id?`Submission ${response.result.submission_id} was admitted.`:"The submission was admitted."})}catch(cause){const deterministic=cause instanceof APIProblem&&!["unavailable","operation_unavailable"].includes(cause.problem.code);if(!deterministic){submissionState.value="uncertain";error.value="The connection ended before submission was confirmed. Do not retry; inspect the delivery queue first."}else error.value=message(cause,"The message could not be submitted.")}finally{if(controllers.send===controller)sending.value=false}}

function onMessageKeys(event:KeyboardEvent):void{if(!messages.value.length)return;if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();const delta=event.key==="ArrowDown"?1:-1;focusedMessage.value=Math.max(0,Math.min(messages.value.length-1,focusedMessage.value+delta));const focused=messages.value[focusedMessage.value];if(focused)document.getElementById(messageDOMID(focused))?.focus()}else if(event.key==="Enter"){event.preventDefault();const focused=messages.value[focusedMessage.value];if(focused)void readMessage(focused)}else if(event.key==="Escape"){selected.value=null;clearRemoteImages()}}
function messageDOMID(item:MessageSummary):string{return `webmail-message-${item.identity.uid_validity}-${item.identity.uid}`}
function addresses(value:string):Address[]{return value.split(/[\s,;]+/).map((item)=>item.trim()).filter(Boolean).map((address)=>({address}))}
function replySubject(value:string,mode:string):string{if(mode==="new")return "";const prefix=mode==="forward"?"Fwd:":"Re:";return value.toLowerCase().startsWith(prefix.toLowerCase())?value:`${prefix} ${value}`.trim()}
function formatDate(value:string):string{const date=new Date(value);return Number.isNaN(date.valueOf())?"":new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(date)}
function initials(value:string):string{return value.split(/[^a-z0-9]+/i).filter(Boolean).map((part)=>part[0]).join("").slice(0,2).toUpperCase()||"?"}
function safeFilename(value:string):boolean{return Boolean(value)&&value.length<=255&&!/[\x00-\x1f/\\]/.test(value)}
function escapeHTML(value:string):string{return value.replace(/[&<>"']/g,(character)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[character]||character))}
function escapeAttribute(value:string):string{return escapeHTML(value)}
function encodeBase64(bytes:Uint8Array):string{let binary="";for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));return btoa(binary)}
function decodeBase64(value:string):Uint8Array<ArrayBuffer>{const padded=value+"=".repeat((4-value.length%4)%4);const binary=atob(padded);return Uint8Array.from(binary,(character)=>character.charCodeAt(0))}
</script>

<template>
  <main class="webmail-page" @keydown.esc="selected=null;clearRemoteImages()">
    <header class="mail-head">
      <div><p>SECURE WEBMAIL / {{selectedAccount?.address||'NO ACCOUNT'}}</p><h2>Webmail</h2></div>
      <div class="head-actions">
        <label class="account-picker"><span>Mail account</span><select :value="mailboxID" :disabled="booting" @change="switchAccount"><option v-for="account in accounts" :key="account.id" :value="account.id">{{account.display_label||account.address}}</option></select></label>
        <button v-if="accountNextCursor" class="button button-small" type="button" @click="moreAccounts">More accounts</button>
        <button class="button button-small" type="button" :disabled="booting" @click="bootstrap"><ArrowClockwise :size="15"/>Refresh</button>
        <button v-if="canCompose" class="button button-primary" type="button" @click="openCompose()"><Plus :size="15"/>Compose</button>
      </div>
    </header>
    <p class="sr-only" aria-live="polite">{{status}}</p><div v-if="error" class="mail-error" role="alert">{{error}}</div>
    <section class="mail-workspace" aria-label="Mailbox">
      <nav class="folder-list" aria-label="Mail folders">
        <button v-for="folder in folders" :key="folder.name" type="button" :class="{active:folder.name===activeFolder}" :aria-current="folder.name===activeFolder?'page':false" @click="activeFolder=folder.name"><span>{{folder.name}}</span><small v-if="folder.unseen">{{folder.unseen}}</small></button>
        <button v-if="folderNextCursor" class="load-more" type="button" @click="moreFolders">Load more folders</button>
      </nav>
      <section class="message-list" aria-label="Messages" @keydown="onMessageKeys">
        <header><form role="search" @submit.prevent="submitSearch"><MagnifyingGlass :size="15"/><label class="sr-only" for="webmail-search">Search this folder</label><input id="webmail-search" v-model="query" type="search" maxlength="256" placeholder="Search this folder"/></form></header>
        <div v-if="listLoading&&!messages.length" class="mail-loading" aria-label="Loading messages"><span v-for="i in 9" :key="i" class="skeleton"></span></div>
        <div v-else class="message-options" role="listbox" aria-label="Message results">
